import re

def parse(lines):
    hdr = None
    starts = []
    names = []
    recs = []
    used = []
    skip = []
    cur = {}
    curl = []
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if re.match(r'^\s*Vserver\s+Volume', l):
            hdr = l
            starts = []
            used.append(i)
            continue
        if hdr is None:
            skip.append(i)
            continue
        if re.match(r'^[\s-]+$', l):
            starts = [m.start() for m in re.finditer(r'-+', l)]
            names = []
            for k, s in enumerate(starts):
                e = starts[k + 1] if k + 1 < len(starts) else len(hdr)
                names.append(hdr[s:e].strip() or 'col%d' % k)
            used.append(i)
            continue
        if re.search(r'entr(y|ies) (were|was) displayed|::>', l) or not starts:
            skip.append(i)
            continue
        for m in re.finditer(r'\S+', l):
            idx = 0
            for k, s in enumerate(starts):
                if s <= m.start():
                    idx = k
            cur[names[idx]] = m.group(0)
        curl.append(i)
        if names[-1] in cur:
            recs.append(dict((n, cur.get(n, '')) for n in names))
            used.extend(curl)
            cur = {}
            curl = []
    if cur and names:
        recs.append(dict((n, cur.get(n, '')) for n in names))
        used.extend(curl)
    return {'blocks': [{'name': 'volumes', 'kind': 'table', 'lines': used, 'records': recs}], 'skip': skip}
